export const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
export const date=v=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Fortaleza'}).format(new Date(v));
export const price=v=>`<div class="price"><small>A partir de</small><strong>${money(v)}</strong></div>`;
export const badge=s=>`<span class="badge ${s==='Lançamento'?'launch':''}">${escapeHTML(s)}</span>`;
export function propertyCard(p){return `<article class="card"><div class="photo"><img src="${p.image}" alt="Foto ilustrativa de edifício residencial" width="600" height="400" loading="lazy">${badge(p.status)}</div><div class="card-body"><span class="builder">${p.builder}</span><h3>${p.name}</h3><div class="location">${p.neighborhood} · ${p.city}</div><div class="spec"><span>${p.typology}</span><span>${p.minArea}–${p.maxArea} m²</span></div><div class="card-bottom">${price(p.price)}<a class="action" href="./?empreendimento=${p.id}" aria-label="Acessar materiais de ${p.name}">Acessar Materiais</a></div></div></article>`;}
export function recentCard(p){return `<a class="recent-card" href="./?empreendimento=${p.id}#materiais"><div class="doc-icon">CSV</div><div><strong>${p.name}</strong><span>Tabela de preços atualizada</span><time datetime="${p.materials.tabela.updatedAt}">${date(p.materials.tabela.updatedAt)}</time></div></a>`;}
export function materialCard(key,m,types){if(!m?.url)return '';const [label,type]=types[key];return `<a class="material" href="${escapeHTML(m.url)}" target="_blank" rel="noopener noreferrer"><div class="doc-icon">${type}</div><div><strong>${label}</strong><small>${m.updatedAt?`Atualizada em ${date(m.updatedAt)} · horário de Brasília`:'Abrir material em nova aba'}</small></div></a>`;}
